const sleepFirst='2026-09-01';
const shiftDay=(day,n)=>{const d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
const clockTime=m=>String(Math.floor(m/60)%24).padStart(2,'0')+':'+String(m%60).padStart(2,'0');
const duration=m=>`${Math.floor(m/60)}시간 ${m%60}분`;
function nightData(day){if(day<sleepFirst||day>M.TODAY)return null;const v=data('sumin',day),d=Number(day.slice(-2)),today=day===M.TODAY,awake=today?22:15+d%18,deep=today?91:Math.round(v.sleep*.2),rem=today?92:Math.round(v.sleep*.23),light=v.sleep-deep-rem,start=today?12:10+d%38;const chunks={awake:[Math.floor(awake/2),awake-Math.floor(awake/2)],deep:[Math.floor(deep*.6),deep-Math.floor(deep*.6)],rem:[Math.floor(rem*.4),rem-Math.floor(rem*.4)],light:[Math.floor(light*.3),Math.floor(light*.25),Math.floor(light*.25)]};chunks.light.push(light-chunks.light.reduce((a,b)=>a+b,0));const order=['light','deep','light','rem','awake','light','deep','light','rem','awake'];const used={light:0,deep:0,rem:0,awake:0};const segments=order.map(k=>({kind:k,minutes:chunks[k][used[k]++]}));return{...v,awake,deep,rem,light,start,end:start+v.sleep+awake,segments,efficiency:Math.round(v.sleep/(v.sleep+awake)*100)}}
function nightGraph(n){if(window.SAISwiftCharts)return window.SAISwiftCharts.sleepStagesChart(n);const levels={awake:20,rem:55,light:90,deep:125},colors={awake:'#E2CBA9',rem:'#E86D13',light:'#8C5A3C',deep:'#30231B'},labels={awake:'깨어 있음',rem:'REM',light:'얕은 수면',deep:'깊은 수면'};let offset=0;return `<svg class="night-chart figma-svg-chart" viewBox="0 0 320 165" role="img" aria-label="선택한 밤의 수면 단계 그래프"><title>깨어 있음 ${n.awake}분, REM ${n.rem}분, 얕은 수면 ${n.light}분, 깊은 수면 ${n.deep}분</title>${Object.entries(levels).map(([k,y])=>`<text x="0" y="${y+3}" fill="#766559">${labels[k]}</text><line x1="56" x2="314" y1="${y}" y2="${y}" stroke="#E3D7C4" stroke-dasharray="3 3"/>`).join('')}${n.segments.map(seg=>{const x=56+offset/(n.sleep+n.awake)*258,w=seg.minutes/(n.sleep+n.awake)*258;offset+=seg.minutes;return `<rect x="${x}" y="${levels[seg.kind]-7}" width="${Math.max(.5,w-1)}" height="14" rx="4" fill="${colors[seg.kind]}"><title>${labels[seg.kind]} ${seg.minutes}분</title></rect>`}).join('')}<text x="56" y="159" fill="#766559">${clockTime(n.start)}</text><text x="314" y="159" text-anchor="end" fill="#766559">${clockTime(n.end)}</text></svg>`}
function sleepDatePicker(){return SAIWeek.render({id:'sleep-week',compact:true,label:'수면',day:sleepDay,min:sleepFirst,max:M.TODAY,legend:'',getGauge:day=>{const n=nightData(day);return n?{values:[n.score/100],label:'수면 '+duration(n.sleep)+' · '+n.score+'점'}:null},onSelect:day=>{sleepDay=day;sleepMonth=day.slice(0,7);sleepCalendarOpen=false;render()}})}
function sleepTabs(){return SAIWeek.header('MY SLEEP','data-x="sleep-tab" data-tab="day"','data-x="sleep-tab" data-tab="trend"',sleepTab==='trend')}
function sleepTrendsPage(){const rows=Array.from({length:sleepPeriod},(_,i)=>{const day=shiftDay(M.TODAY,-sleepPeriod+1+i);return{day,night:nightData(day)}}).filter(r=>r.night);const avgScore=Math.round(rows.reduce((a,r)=>a+r.night.score,0)/rows.length),avgSleep=Math.round(rows.reduce((a,r)=>a+r.night.sleep,0)/rows.length);return formPage(sleepTabs()+`<div class="chips">${[7,30].map(v=>X(v+'일','sleep-period',{period:v},sleepPeriod===v?'on':'')).join('')}</div><div class="figma-detail-hero"><span class="figma-detail-label">최근 ${rows.length}일 평균 ${sleepTrendMetric==='score'?'수면 점수':'수면 시간'}</span><strong class="figma-detail-big">${sleepTrendMetric==='score'?avgScore+'점':`${Math.floor(avgSleep/60)}시간 ${avgSleep%60}분`}</strong><p class="figma-detail-sub">${rows[0].day.replaceAll('-','.')} – ${M.TODAY.replaceAll('-','.')} · 평균 ${sleepTrendMetric==='score'?`${Math.floor(avgSleep/60)}시간 ${avgSleep%60}분 수면`:`수면 점수 ${avgScore}점`}</p></div><div class="chips">${[['score','수면 점수'],['sleep','수면 시간']].map(([key,label])=>X(label,'sleep-trend-metric',{metric:key},sleepTrendMetric===key?'on':'')).join('')}</div><div class="trend-panel"><span class="eyebrow">${sleepTrendMetric==='score'?'수면 점수':'수면 시간'}의 흐름</span>${trendChart(rows.map(r=>({day:r.day,v:r.night[sleepTrendMetric]})),sleepTrendMetric,'')}<p class="tiny">실선: 일별 기록 · 점선: 기간 평균</p></div><section class="figma-bottom-sheet"><div class="figma-sheet-section-head"><h3>날짜별 수면 기록</h3><small>${rows.length}일</small></div><div class="figma-record-list">${[...rows].reverse().map(r=>`<button class="row" data-x="sleep-trend-day" data-date="${r.day}"><span class="grow"><strong>${r.day.replaceAll('-','.')} · ${duration(r.night.sleep)}</strong><small>수면 점수 ${r.night.score}점 · 효율 ${r.night.efficiency}%</small></span><span class="arrow">→</span></button>`).join('')}</div><div class="push" style="margin-top:18px">${X('어젯밤 수면으로 돌아가기','sleep-tab',{tab:'day'},'primary')}</div></section>`)}
function sleepPage(){if(sleepTab==='trend')return sleepTrendsPage();const n=nightData(sleepDay);const picker=sleepDatePicker();const head=sleepTabs();if(!n)return formPage(head+picker+msg('이 날짜에는 수면 기록이 없어요.<br>달력에서 기록이 있는 날짜를 골라주세요.')+X('최근 수면 보기','sleep-day',{date:M.TODAY},'primary'));const totalMin=n.sleep+n.awake;const deepPct=Math.round(n.deep/totalMin*100),lightPct=Math.round(n.light/totalMin*100),remPct=Math.round(n.rem/totalMin*100),awakePct=Math.max(1,100-deepPct-lightPct-remPct);return formPage(head+picker+`<div class="figma-detail-hero"><span class="figma-detail-label">${sleepDay===M.TODAY?'어젯밤 수면':Number(sleepDay.slice(5,7))+'월 '+Number(sleepDay.slice(8))+'일 수면'}</span><strong class="figma-detail-big">${duration(n.sleep)}</strong><p class="figma-detail-sub">${clockTime(n.start)} 잠듦 · ${clockTime(n.end)} 기상 · 수면 점수 ${n.score}</p></div><div class="swift-chart-card"><div class="swift-chart-head"><span>수면 단계 타임라인</span><button type="button" class="figma-sheet-link" data-x="sleep-tab" data-tab="trend">추이 보기 →</button></div>${nightGraph(n)}</div><section class="figma-bottom-sheet"><div class="figma-sheet-section-head"><h3>수면 단계 비율</h3><small>효율 ${n.efficiency}%</small></div><div class="figma-sleep-stage-bar" role="img" aria-label="수면 단계 비율"><span class="stage-deep" style="width:${deepPct}%"></span><span class="stage-light" style="width:${lightPct}%"></span><span class="stage-rem" style="width:${remPct}%"></span><span class="stage-awake" style="width:${awakePct}%"></span></div><div class="figma-stage-axis"><span>${clockTime(n.start)}</span><span>03:30</span><span>${clockTime(n.end)}</span></div><div class="figma-record-list"><div class="figma-stage-row"><span class="stage-dot stage-deep"></span><div class="grow"><strong>깊은 수면 · ${deepPct}%</strong><small>몸의 피로를 회복하는 시간</small></div><b class="figma-stage-val">${duration(n.deep)}</b></div><div class="figma-stage-row"><span class="stage-dot stage-light"></span><div class="grow"><strong>얕은 수면 · ${lightPct}%</strong><small>안정적으로 이어진 수면</small></div><b class="figma-stage-val">${duration(n.light)}</b></div><div class="figma-stage-row"><span class="stage-dot stage-rem"></span><div class="grow"><strong>REM 수면 · ${remPct}%</strong><small>기억과 감정을 정리하는 시간</small></div><b class="figma-stage-val">${duration(n.rem)}</b></div><div class="figma-stage-row"><span class="stage-dot stage-awake"></span><div class="grow"><strong>깨어남 · ${awakePct}%</strong><small>수면 효율 ${n.efficiency}%</small></div><b class="figma-stage-val">${n.awake}분</b></div></div>`+(window.SAISDKExperience?.napCard(sleepDay)||'')+`<h3 class="figma-section-h3">밤사이 생체 리듬</h3><div class="sai-bento-grid"><div class="sai-bento-card"><small>안정 심박</small><strong>${n.bpm} bpm</strong><span>밤사이 최저 평균</span></div><div class="sai-bento-card"><small>심박변이도 (HRV)</small><strong>${n.hrv} ms</strong><span>자율신경 회복 지표</span></div><div class="sai-bento-card"><small>혈중 산소 (SpO2)</small><strong>${n.oxygen}%</strong><span>호흡 안정도 양호</span></div><div class="sai-bento-card"><small>피부 온도 편차</small><strong>${value(n.temp,'temp')}</strong><span>기준선 대비 안정</span></div></div><div class="push" style="margin-top:20px">${btn('나의 아침 나누기','morning','primary')}</div></section>`)}
function trendChart(rows,key,selected,band){if(window.SAISwiftCharts){const selIdx=rows.findIndex(r=>r.day===selected);const labels=band?rows.map((_,i)=>i===0?'1일':i===13?'14일':i===rows.length-1?'28일':''):rows.map(r=>r.day.slice(5).replace('-','.'));const formatTick=v=>key==='sleep'?(v/60).toFixed(1)+'h':key==='temp'?(v>=0?'+':'')+v.toFixed(1)+'°':Math.round(v);return window.SAISwiftCharts.lineAreaChart({values:rows.map(r=>r.v),labels,band,selectedIndex:selIdx>=0?selIdx:rows.length-1,formatTick,formatCallout:(v,i)=>`${rows[i]?.day?.slice(5)?.replace('-','.')||rows[i]?.day||''} · ${value(v,key)}`,ariaLabel:`${metrics[key]?.label||key} 추세 그래프`});}const width=320,left=44,right=308,top=18,bottom=168;const values=rows.map(r=>r.v);const all=band?[...values,...band.flat()]:values;let lo=Math.min(...all),hi=Math.max(...all);const pad=Math.max((hi-lo)*.18,key==='temp'?.05:1);lo-=pad;hi+=pad;if(key==='score'){lo=0;hi=100}const y=v=>bottom-(v-lo)/(hi-lo)*(bottom-top),x=i=>left+i*(right-left)/Math.max(1,rows.length-1),mean=values.reduce((a,b)=>a+b,0)/values.length;const tick=v=>key==='sleep'?(v/60).toFixed(1)+'h':key==='temp'?v.toFixed(1):Math.round(v);const pts=rows.map((r,i)=>[x(i),y(r.v)]);const linePath=pts.map((p,i)=>i===0?`M${p[0].toFixed(1)},${p[1].toFixed(1)}`:`L${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(' ');const areaPath=`${linePath} L${pts.at(-1)[0].toFixed(1)},${bottom} L${pts[0][0].toFixed(1)},${bottom} Z`;const gradId=`trendGrad_${key}_${rows.length}`;return `<svg class="trend-chart figma-svg-chart" viewBox="0 0 ${width} 202" role="img" aria-label="${metrics[key].label} 추세 그래프${band?' · 과거 주기 범위 포함':''}"><defs><linearGradient id="${gradId}" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#E86D13" stop-opacity="0.24"/><stop offset="100%" stop-color="#E86D13" stop-opacity="0.0"/></linearGradient></defs>${[lo,(lo+hi)/2,hi].map(v=>`<line x1="${left}" x2="${right}" y1="${y(v)}" y2="${y(v)}" stroke="#E3D7C4" stroke-dasharray="3 3"/><text x="${left-6}" y="${y(v)+3}" text-anchor="end" fill="#766559" font-size="10">${tick(v)}</text>`).join('')}${band?`<polygon points="${band.map((r,i)=>x(i)+','+y(r[1])).join(' ')} ${[...band].reverse().map((r,i)=>x(rows.length-1-i)+','+y(r[0])).join(' ')}" fill="#E6D6BE" opacity=".55"/>`:`<path d="${areaPath}" fill="url(#${gradId})"/><line x1="${left}" x2="${right}" y1="${y(mean)}" y2="${y(mean)}" stroke="#C7B69E" stroke-dasharray="4 4"/>`}<path d="${linePath}" fill="none" stroke="#E86D13" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/>${rows.map((r,i)=>`<circle cx="${x(i)}" cy="${y(r.v)}" r="${r.day===selected?5.5:3}" fill="${band&&(r.v<band[i][0]||r.v>band[i][1])?'#30231B':r.day===selected?'#30231B':'#E86D13'}" stroke="#FEF8EF" stroke-width="1.5"><title>${r.day}: ${value(r.v,key)}</title></circle>`).join('')}<text x="${left}" y="192" fill="#766559" font-size="10">${band?'1일':rows[0].day.slice(5)}</text><text x="${right}" y="192" text-anchor="end" fill="#766559" font-size="10">${band?'28일':rows.at(-1).day.slice(5)}</text></svg>`}
let healthView='day';
Object.assign(metrics,{activityScore:{label:'활동 목표 달성률',unit:'%'},energy:{label:'에너지 점수',unit:'점'},stress:{label:'스트레스',unit:'점'},heartAvg:{label:'평균 심박',unit:'bpm'}});
const healthData=day=>({...data('sumin',day),...(window.SAIHealthCards?.values(day)||{activityScore:0,energy:84,stress:39,heartAvg:72})});
function healthPage(){const header=SAIWeek.header('MY HEALTH','data-x="health-view" data-view="day"','data-x="health-view" data-view="trend"',healthView==='trend');const picker=()=>SAIWeek.render({id:'health-week',compact:true,label:'건강 기록',day:selectedDay,min:shiftDay(M.TODAY,-29),max:M.TODAY,legend:'기록 유무',getGauge:day=>({values:[1],label:metrics[metric].label+' '+value(healthData(day)[metric],metric)}),onSelect:day=>{selectedDay=day;render()}});const pillTabs=`<div class="lens-pills" role="tablist" aria-label="건강 지표 선택">${[['sleep','수면'],['bpm','심박'],['hrv','HRV'],['temp','온도'],['steps','활동']].map(([k,l])=>`<button type="button" class="${metric===k?'on':''}" data-x="metric" data-metric="${k}">${l}</button>`).join('')}</div>`;const rows7=Array.from({length:7},(_,i)=>{const day=shiftDay(selectedDay,-6+i);return{day,v:healthData(day)[metric]}});const vals7=rows7.map(r=>r.v),avg7=vals7.reduce((a,b)=>a+b,0)/vals7.length;const hd=healthData(selectedDay);
if(healthView==='day')return formPage(header+picker()+pillTabs+`<div class="figma-detail-hero"><span class="figma-detail-label">${metrics[metric]?.label||'수면 시간'} · 주간 평균</span><strong class="figma-detail-big">${value(avg7,metric)}</strong><p class="figma-detail-sub">${Number(selectedDay.slice(5,7))}월 ${Number(selectedDay.slice(8))}일 기록 ${value(hd[metric],metric)} · 안정적인 흐름</p></div><div class="swift-chart-card"><div class="swift-chart-head"><span>최근 7일 ${metrics[metric]?.label||'지표'} 흐름</span><button type="button" class="figma-sheet-link" data-x="health-view" data-view="trend">30일 추이 →</button></div>${trendChart(rows7,metric,selectedDay)}</div><section class="figma-bottom-sheet"><div class="figma-sheet-section-head"><h3>${Number(selectedDay.slice(5,7))}월 ${Number(selectedDay.slice(8))}일 바이오메트릭 요약</h3><small>SAI_11C1</small></div><div class="sai-bento-grid">${[['sleep','수면 시간','깊은 수면·효율'],['bpm','안정 심박','수면 중 최저'],['hrv','심박변이도','자율신경 회복'],['temp','피부 온도','기준선 편차']].map(([k,label,sub])=>`<button type="button" class="sai-bento-card is-interactive" data-x="health-metric-row" data-metric="${k}"><small>${label}</small><strong>${value(hd[k],k)}</strong><span>${sub} →</span></button>`).join('')}</div><div class="figma-record-list" style="margin-top:10px"><button type="button" class="row" data-x="health-metric-row" data-metric="steps"><span class="grow"><strong>오늘의 걸음 · ${value(hd.steps,'steps')}</strong><small>일일 활동량과 걸음 추이</small></span><span class="arrow">→</span></button></div><details class="sleep-details" style="margin-top:14px"><summary>센서 정밀 리포트 (혈중 산소·에너지·스트레스) 보기</summary>${window.SAIHealthCards?.render(selectedDay)||''}</details><div class="push" style="margin-top:18px">${btn('나의 주기 기록과 함께 보기','cycle-insights','secondary')}</div></section>`);
const rows=Array.from({length:period},(_,i)=>{const day=shiftDay(M.TODAY,-period+1+i);return{day,v:healthData(day)[metric]}}),vals=rows.map(r=>r.v),avg=vals.reduce((a,b)=>a+b,0)/vals.length;return formPage(header+`<div class="chips">${[7,30].map(n=>X(n+'일','period',{period:n},period===n?'on':'')).join('')}</div>`+pillTabs+`<div class="figma-detail-hero"><span class="figma-detail-label">${metrics[metric].label} · ${period}일 평균</span><strong class="figma-detail-big">${value(avg,metric)}</strong><p class="figma-detail-sub">${rows[0].day.replaceAll('-','.')} – ${M.TODAY.replaceAll('-','.')}</p></div><div class="swift-chart-card"><div class="swift-chart-head"><span>${period}일 ${metrics[metric].label} 추이</span><small>Apple Swift Charts</small></div>${trendChart(rows,metric,'')}</div><section class="figma-bottom-sheet"><div class="sai-bento-grid"><div class="sai-bento-card"><small>기간 최솟값</small><strong>${value(Math.min(...vals),metric)}</strong><span>안정 하한</span></div><div class="sai-bento-card"><small>기간 최댓값</small><strong>${value(Math.max(...vals),metric)}</strong><span>최고 기록</span></div></div><div class="figma-record-list" style="margin-top:12px">${[...rows].reverse().slice(0,7).map(r=>`<button class="row" data-x="health-day" data-date="${r.day}"><span class="grow"><strong>${r.day.replaceAll('-','.')}</strong><small>${metrics[metric].label} ${value(r.v,metric)}</small></span><span class="arrow">→</span></button>`).join('')}</div><div class="push" style="margin-top:18px">${X('오늘의 바이오메트릭 요약으로','health-view',{view:'day'},'primary')}</div></section>`)}

const cycleSymptoms={none:'특별한 변화 없음',tired:'피로',cramps:'복부 불편감',headache:'두통',bloating:'더부룩함'};
const cycleFlows={light:'적음',medium:'보통',heavy:'많음'};
function cyclePrediction(){if(!cycleRecords.length)return{start:'2026-10-24',end:'2026-10-28',basis:''};const intervals=cycleRecords.slice(1).map((r,i)=>Math.round((new Date(r.start+'T12:00:00Z')-new Date(cycleRecords[i].start+'T12:00:00Z'))/86400000)).sort((a,b)=>a-b);const middle=Math.floor(intervals.length/2),length=intervals.length?(intervals.length%2?intervals[middle]:Math.round((intervals[middle-1]+intervals[middle])/2)):28;const center=shiftDay(cycleRecords.at(-1).start,length);return{start:shiftDay(center,-2),end:shiftDay(center,2),basis:intervals.length?'입력한 시작일 간격을 바탕으로 산출된 예상 기간':'평균 28일 주기를 바탕으로 산출된 예상 기간'}}
const cycleDateLabel=d=>Number(d.slice(5,7))+'월 '+Number(d.slice(8))+'일';
function predictionCard(p){return `<section class="cycle-prediction"><span class="eyebrow">다음 생리 시작 예상 기간</span><h3>${cycleDateLabel(p.start)} – ${cycleDateLabel(p.end)}</h3><p>${p.end<M.TODAY?'예상 기간이 지났어요. 실제 시작일을 남겨주세요.':'몸의 흐름에 따라 예상 기간은 달라질 수 있어요.'}</p>${p.basis?`<small>${p.basis}</small>`:''}<div class="push">${X('생리가 시작됐어요','cycle-actual',{},'primary')}${X('예상 기간 달력에서 보기','cycle-prediction-month',{},'text-btn')}</div></section>`}
function cyclePage(){const prediction=cyclePrediction();const [year,month]=cycleMonth.split('-').map(Number),count=new Date(Date.UTC(year,month,0)).getUTCDate(),offset=(new Date(Date.UTC(year,month-1,1)).getUTCDay()+6)%7;const last=cycleRecords.at(-1);return page('cycle','나의 주기를<br>차곡차곡','예상 기간을 확인하고, 실제 시작일을 남겨주세요.',`<div class="figma-detail-hero"><span class="figma-detail-label">현재 주기 상태</span><strong class="figma-detail-big">주기 14일째</strong><p class="figma-detail-sub">다음 예정일 ${cycleDateLabel(prediction.start)} – ${cycleDateLabel(prediction.end)} · 배란기 추정</p></div><div class="figma-cycle-phase-bar" role="img" aria-label="주기 단계 바"><span class="phase-menstrual" style="width:18%"></span><span class="phase-follicular" style="width:28%"></span><span class="phase-ovulation" style="width:16%"><i></i></span><span class="phase-luteal" style="width:38%"></span></div><div class="figma-stage-axis"><span>생리기</span><span>여포기</span><span>배란기</span><span>황체기</span></div><section class="figma-bottom-sheet"><div class="figma-record-list"><button type="button" class="row" data-x="cycle-actual"><span class="grow"><strong>생리가 시작됐어요 · 오늘 기록하기</strong><small>시작일과 몸의 느낌, 생리 양을 남겨요</small></span><span class="arrow">→</span></button><button type="button" class="row" data-go="cycle-insights"><span class="grow"><strong>주기와 몸의 변화 비교하기</strong><small>피부 온도 편차 · 심박 · HRV 추이</small></span><span class="arrow">→</span></button></div><div class="month-nav" style="margin-top:20px">${X('‹ 이전','cycle-month',{delta:-1})}<h3>${year}년 ${month}월</h3>${X('다음 ›','cycle-month',{delta:1})}</div><div class="calendar cycle-calendar">${['월','화','수','목','금','토','일'].map(d=>`<small>${d}</small>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:count},(_,i)=>{const day=cycleMonth+'-'+String(i+1).padStart(2,'0'),record=cycleRecords.find(r=>day>=r.start&&day<=(r.end||r.start));return `<button data-x="cycle-day" data-date="${day}" ${day>M.TODAY?'disabled':''} class="${record?'logged':day>=prediction.start&&day<=prediction.end?'predicted':''}" aria-label="${day}${record?' 실제 생리 기록':day>=prediction.start&&day<=prediction.end?' 예상 시작 기간':''}">${i+1}</button>`}).join('')}</div><p class="tiny">주황색: 실제 생리일 · 점선: 예상 시작 기간</p>${last?msg('최근 시작일 '+last.start+(last.end?' · 종료일 '+last.end:' · 종료일 미입력')):''}<div class="push" style="margin-top:16px">${X('생리 기록하기','cycle-new',{},'primary')}</div>${cycleRecords.length?`<h3 class="figma-section-h3">나의 기록</h3><div class="figma-record-list">${[...cycleRecords].reverse().map(r=>`<button class="row" data-x="cycle-edit" data-date="${r.start}"><span class="grow"><strong>${r.start}${r.end?' → '+r.end:''}</strong><small>${cycleSymptoms[r.symptom]} · 양 ${cycleFlows[r.flow]}</small></span><span class="arrow">→</span></button><div class="cycle-share-actions">${X(cycleShares.some(s=>s.start===r.start)?'공유 내용 다시 선택':'파트너에게 공유하기','cycle-share-open',{date:r.start},'secondary')}${cycleShares.some(s=>s.start===r.start)?X('공유 해제','cycle-unshare',{date:r.start},'text-btn'):''}</div>`).join('')}</div>`:''}</section>`,true)}
function cycleSharePage(){const r=cycleRecords.find(r=>r.start===cycleShareStart);if(!r)return page('cycle-share','공유할 기록을<br>선택해 주세요','저장한 생리 기록에서 공유할 수 있어요.',btn('나의 주기 기록 보기','cycle','primary'),true);return page('cycle-share','필요한 만큼만<br>함께 알아가요','공유한 날짜는 두 사람의 순간 캘린더에 표시돼요.',`<div class="share-card"><span class="eyebrow">공유할 생리 날짜</span><h3 style="margin-top:12px">${r.start}${r.end?' → '+r.end:''}</h3><p>${r.end?'시작일부터 종료일까지 표시해요.':'종료일이 없어 시작일만 표시해요.'}</p></div>${[['symptom','몸의 느낌',cycleSymptoms[r.symptom]],['flow','생리 양',cycleFlows[r.flow]],['note','메모',r.note]].filter(x=>x[2]).map(([key,label,v])=>`<label class="check-row"><input type="checkbox" data-cycle-field="${key}"><span>${label}도 공유하기<small>${esc(v)}</small></span></label>`).join('')}<p class="tiny">주기별 분석과 다른 기록은 포함되지 않아요.</p>${state.paired?consent('위 날짜와 체크한 내용을 윤서에게 공유할게요.')+X('공유하고 캘린더 보기','cycle-share-send',{},'primary'):msg('파트너 연결 후 공유할 수 있어요.')+btn('파트너 연결하기','invite','primary')}${btn('돌아가기','cycle','text-btn')}`,true)}
function visibleCycles(){return who==='sumin'?cycleRecords.map(r=>({...r,shared:state.paired&&cycleShares.some(s=>s.start===r.start)})):state.paired?cycleShares:[]}
function cycleCalendarCards(day){return visibleCycles().filter(r=>day>=r.start&&day<=(r.end||r.start)).map(r=>`<div class="moment cycle-calendar-card"><small>${who==='sumin'?(r.shared?'파트너에게 공유한 생리 기록':'나만의 생리 기록'):esc(person('sumin'))+'님이 공유한 생리 기록'}</small><h3 style="margin-top:10px">생리 기록</h3><p>${r.start}${r.end?' → '+r.end:''}</p>${r.symptom?`<p>몸의 느낌 · ${cycleSymptoms[r.symptom]}</p>`:''}${r.flow?`<p>생리 양 · ${cycleFlows[r.flow]}</p>`:''}${r.note?`<p class="cycle-shared-note">${esc(r.note)}</p>`:''}${who==='sumin'?X(r.shared?'공유 내용 다시 선택':'파트너에게 공유하기','cycle-share-open',{date:r.start},'secondary')+(r.shared?X('공유 해제','cycle-unshare',{date:r.start},'text-btn'):''):''}</div>`).join('')}
function revokeCycle(start){const removed=cycleShares.filter(r=>r.start===start).map(r=>r.id);cycleShares=cycleShares.filter(r=>r.start!==start);pair.notices=pair.notices.filter(n=>!removed.includes(n.target))}
function cycleLogPage(){const r=cycleDraft;return page('cycle-log','오늘의 몸을<br>기록해요','실제 시작한 날짜를 확인해 주세요.',(r.prediction?msg('입력 전 예상 기간: '+cycleDateLabel(r.prediction.start)+' – '+cycleDateLabel(r.prediction.end)):'')+`<div class="field"><label for="cycle-start">생리 시작일</label><input id="cycle-start" type="date" min="2026-01-01" max="${M.TODAY}" value="${r.start||''}"></div><div class="field"><label for="cycle-end">생리 종료일 · 선택</label><input id="cycle-end" type="date" min="${r.start||'2026-01-01'}" max="${M.TODAY}" value="${r.end||''}"></div><div class="field"><label for="cycle-symptom">몸의 느낌</label><select id="cycle-symptom">${Object.entries(cycleSymptoms).map(([k,v])=>`<option value="${k}" ${r.symptom===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="cycle-flow">생리 양</label><select id="cycle-flow">${Object.entries(cycleFlows).map(([k,v])=>`<option value="${k}" ${(r.flow||'medium')===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="cycle-note">메모 · 선택</label><textarea id="cycle-note" maxlength="160" placeholder="오늘 느낀 변화를 적어주세요">${esc(r.note||'')}</textarea></div>${X('나의 주기 저장하기','cycle-save',{},'primary')}${btn('기록으로 돌아가기','cycle','text-btn')}`,true)}
function cycleInsightsPage(){const centers=Array.from({length:28},(_,i)=>cycleMetric==='temp'?(i<14?-.15:.18):cycleMetric==='bpm'?(i<14?57:61):(i<14?44:38));const spread=cycleMetric==='temp'?.12:cycleMetric==='bpm'?3:6;const rows=centers.map((v,i)=>({day:'주기 '+(i+1)+'일',v:v+(i===18?(cycleMetric==='temp'?.35:cycleMetric==='bpm'?7:-12):Math.sin(i)*spread*.4)}));const band=centers.map(v=>[v-spread,v+spread]);const flagged=rows.filter((r,i)=>r.v<band[i][0]||r.v>band[i][1]);const latestVal=rows[13].v;return page('cycle-insights','주기 속에서<br>나의 변화를 읽어요','주기에 따라 달라지는 몸의 흐름을 같은 시점끼리 비교해요.',`<div class="figma-detail-hero"><span class="figma-detail-label">주기 14일째 · ${metrics[cycleMetric].label}</span><strong class="figma-detail-big">${value(latestVal,cycleMetric)}</strong><p class="figma-detail-sub">과거 같은 주기 시점 범위 안에 있어요</p></div><div class="chips">${['temp','bpm','hrv'].map(k=>X(metrics[k].label,'cycle-metric',{metric:k},cycleMetric===k?'on':'')).join('')}</div><div class="trend-panel"><span class="eyebrow">${metrics[cycleMetric].label} / 주기 1–28일</span>${trendChart(rows,cycleMetric,'',band)}<div class="axis"><span>시작일</span><span>28일째</span></div><p class="tiny">실선: 이번 주기 흐름 · 음영: 과거 같은 주기 시점의 평균 범위</p></div><section class="figma-bottom-sheet"><div class="figma-sheet-section-head"><h3>주기 변화 알림</h3><small>${flagged.length}건</small></div>${flagged.map(r=>`<div class="cycle-change"><span class="eyebrow">평소 범위 밖 변화</span><h3>${r.day}의 ${metrics[cycleMetric].label}</h3><p>${value(r.v,cycleMetric)} · 평소 주기 범위를 ${cycleMetric==='hrv'?'밑돌았어요':'웃돌았어요'}.</p><p class="tiny">주기뿐 아니라 수면, 활동, 컨디션과 함께 살펴보세요. 이 값만으로 원인을 단정하지 않아요.</p></div>`).join('')}<p class="tiny" style="margin-top:12px">생리 주기 변화와 질환을 구분하는 의료 진단 기능은 아니에요. 피부 온도는 중심 체온과 달라요.</p><div class="push" style="margin-top:16px">${btn('몸의 느낌 기록하기','cycle-log','primary')}${btn('나의 주기로 돌아가기','cycle','text-btn')}</div></section>`,true)}
const moodLabel=k=>({calm:'편안해요',happy:'기분 좋아요',excited:'설레요',cloudy:'조금 흐려요',tired:'쉬고 싶어요'}[k]||k);
function morningExtras(m){return (m.mood?`<div class="morning-message"><small>오늘의 기분</small><p>${esc(moodLabel(m.mood))}</p></div>`:'')+(m.note?`<div class="morning-message"><small>오늘의 한마디</small><p>${esc(m.note)}</p></div>`:'')}
function morningChoices(){const p=pair.people[who],available=who==='sumin'?!!state.checkinDone||!!state.mood:true;return `<div class="section-label"><span>체크인도 함께 보낼까요?</span><span>선택</span></div>${[['mood','기분 함께 보내기',available?moodLabel(p.mood):'',available],['note','오늘의 한마디 함께 보내기',available?p.note:'',available&&!!p.note]].map(([key,label,value,enabled])=>`<label class="check-row"><input type="checkbox" data-morning-option="${key}" ${morningOptions[who][key]&&enabled?'checked':''} ${enabled?'':'disabled'}><span>${label}<small>${enabled?esc(value):'체크인에서 먼저 남겨주세요.'}</small></span></label>`).join('')}`}
let breathInviteOpened='',breathPeerDetail=false,breathPeerView='today';
function breathPeerToday(){if(breathPeerView==='today')return receiverToday('data-breath-peer-go');const saved=state.peerView;state.peerView=breathPeerView;try{return (formPage(peerPage())+peerNav()).replaceAll('data-peer-go=','data-breath-peer-go=')}finally{state.peerView=saved}}
document.addEventListener('click',e=>{if(e.target.closest('[data-breath-home]')){breathPeerDetail=false;breathPeerView='today';renderBreathPeer();return}const link=e.target.closest('[data-breath-peer-go]');if(link){breathPeerView=['sleep','activity','heart','calendar','settings'].includes(link.dataset.breathPeerGo)?link.dataset.breathPeerGo:'today';renderBreathPeer()}});
function breathChart(hearts,done=false){if(!hearts?.sumin?.length||!hearts?.jiwoo?.length)return '';const colors=['#E86D13','#30231B'],rows=M.USERS.map(id=>hearts[id]);if(window.SAISwiftCharts){const svg=window.SAISwiftCharts.lineAreaChart({values:rows[0].map(p=>p.bpm),secondaryValues:rows[1].map(p=>p.bpm),secondaryColor:'#30231B',labels:rows[0].map((p,i)=>i===0?'0초':i===Math.floor(rows[0].length/2)?'12초':i===rows[0].length-1?'24초':''),unit:'bpm',showMean:false,ariaLabel:'두 사람의 호흡 중 심박 변화, 단위 bpm'});return `<section class="breath-hearts"><h3>${done?'함께 호흡한 심박 기록':'함께 호흡하는 지금의 심박'}</h3><div class="breath-heart-people">${M.USERS.map((id,i)=>`<div style="--heart-color:${colors[i]}"><span>${esc(person(id))}</span><strong>${rows[i].at(-1).bpm}<small> bpm</small></strong>${done?`<small>전체 평균 ${Math.round(rows[i].reduce((a,r)=>a+r.bpm,0)/rows[i].length)} bpm</small>`:''}</div>`).join('')}</div>${svg}${done?window.SAISDKExperience?.breathComparison(hearts)||'':''}</section>`;}const all=rows.flat().map(r=>r.bpm),low=Math.floor((Math.min(...all)-5)/5)*5,high=Math.ceil((Math.max(...all)+5)/5)*5,x=t=>30+t/24*270,y=v=>110-(v-low)/(high-low)*88;return `<section class="breath-hearts"><h3>${done?'함께 호흡한 심박 기록':'함께 호흡하는 지금의 심박'}</h3><div class="breath-heart-people">${M.USERS.map((id,i)=>`<div style="--heart-color:${colors[i]}"><span>${esc(person(id))}</span><strong>${rows[i].at(-1).bpm}<small> bpm</small></strong>${done?`<small>전체 평균 ${Math.round(rows[i].reduce((a,r)=>a+r.bpm,0)/rows[i].length)} bpm</small>`:''}</div>`).join('')}</div><svg class="figma-svg-chart" viewBox="0 0 320 140" role="img" aria-label="두 사람의 호흡 중 심박 변화, 단위 bpm"><defs><linearGradient id="breathGrad0" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#E86D13" stop-opacity="0.22"/><stop offset="100%" stop-color="#E86D13" stop-opacity="0.0"/></linearGradient></defs>${[low,(low+high)/2,high].map(v=>`<line x1="30" x2="300" y1="${y(v)}" y2="${y(v)}" stroke="#E3D7C4" stroke-dasharray="3 4"/><text x="3" y="${y(v)+3}" font-size="9" fill="#766559">${v}</text>`).join('')}${rows.map((r,i)=>{const pts=r.map(p=>x(p.second)+','+y(p.bpm)).join(' ');const area=i===0?`<polygon points="${r.map(p=>x(p.second)+','+y(p.bpm)).join(' ')} ${x(r.at(-1).second)},116 ${x(r[0].second)},116" fill="url(#breathGrad0)"/>`:'';return `${area}<polyline points="${pts}" fill="none" stroke="${colors[i]}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><circle cx="${x(r.at(-1).second)}" cy="${y(r.at(-1).bpm)}" r="4" fill="${colors[i]}" stroke="#FEF8EF" stroke-width="1.5"/>`}).join('')}<text x="30" y="132" font-size="10" fill="#766559">0초</text><text x="158" y="132" font-size="10" fill="#766559">12초</text><text x="282" y="132" font-size="10" fill="#766559">24초</text></svg>${done?window.SAISDKExperience?.breathComparison(hearts)||'':''}</section>`}
function breathScreen(actor){const b=pair.breath,running=b?.status==='running',seconds=running?Math.min(24,Math.floor((Date.now()-b.started)/1000)):0;const button=(label,action,cls='primary')=>`<button class="${cls}" data-breath-action="${action}" data-breath-actor="${actor}">${label}</button>`;const agree=`<label class="check-row"><input type="checkbox" data-breath-consent="${actor}"><span>24초 동안 함께 호흡하며 서로의 심박을 보고, 두 사람의 기록을 공유 캘린더에 남길게요.</span></label>`;let body='';if(!state.paired)body=msg('파트너를 연결하면 함께 호흡할 수 있어요.')+btn('파트너 연결하기','invite');else if(!b||['done','cancelled'].includes(b.status))body=(b?msg(b.status==='done'?'같은 리듬으로 24초를 함께했어요.':'함께 호흡을 중단했어요. 다시 초대할 수 있어요.'):'')+agree+button('함께 호흡하자고 초대하기','invite');else if(b.status==='waiting')body=b.from===actor?msg('초대를 보냈어요. 상대가 수락하면 시작해요.')+button('초대 취소','cancel','text-btn'):breathInviteOpened===b.id?msg('함께 호흡하자는 초대가 왔어요.')+agree+button('수락하고 함께 시작하기','join')+button('지금은 어려워요','cancel','text-btn'):msg('초대가 오면 상단 알림에서 확인해 주세요.');else if(running)body=msg('함께 들이쉬고, 천천히 내쉬어요.')+button('호흡 중단하기','cancel','text-btn');return formPage(SAIWeek.header('BREATHE TOGETHER','','',true,{backAttrs:actor===who?'data-go="together"':'data-breath-home',backLabel:actor===who?'우리로 돌아가기':'오늘로 돌아가기',trendSuffix:false})+title('','잠깐, 같은 리듬으로','초대하고 수락하면 24초 동안 함께 호흡해요.')+`<div class="breath-orb ${running?'running':''}" ${running?`style="animation-delay:-${(Date.now()-b.started)/1000}s"`:''}><span data-breath-phase>${running?(Math.floor(seconds/4)%2?'천천히 내쉬어요':'천천히 들이쉬어요'):'함께, 천천히'}</span><b data-breath-left>${running?24-seconds:b?.status==='done'?0:24}</b><small>초</small></div>`+(['running','done'].includes(b?.status)?`<div data-breath-hearts>${breathChart(b.hearts,b.status==='done')}</div>`:'')+body+`<p class="error" role="alert" data-breath-error="${actor}"></p>`+btn('함께한 기록 보기','calendar','text-btn'))}
function renderBreathPeer(){document.querySelectorAll('.breath-invite-notice').forEach(el=>el.remove());let peer=document.getElementById('breath-peer-device');document.body.classList.toggle('breath-dual',current==='breathing');if(current!=='breathing'){peer?.remove();return}document.body.classList.add('dual-invite');if(!peer){peer=document.createElement('section');peer.id='breath-peer-device';peer.className='device';peer.setAttribute('aria-label','함께 호흡 상대 화면');app.closest('.device').after(peer)}peer.innerHTML=`<div class="status"><b>9:41</b><div>▮▮▮ &nbsp; ◒ &nbsp; ▰</div></div><div class="peer-app">${breathPeerDetail?breathScreen(other()):breathPeerToday()}</div><div class="home-line"></div>`;const b=pair.breath;if(b?.status==='waiting'&&breathInviteOpened!==b.id){const actor=M.other(b.from),device=actor===who?app.closest('.device'):peer;const notice=inviteNotice(esc(person(b.from))+'님이 함께 호흡에 초대했어요','breath-open').replace('data-action="breath-open"',`data-breath-action="open" data-breath-actor="${actor}" data-breath-id="${b.id}"`);device.insertAdjacentHTML('beforeend',`<div class="ios-notification breath-invite-notice">${notice}</div>`);}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-breath-action]');if(!el||current!=='breathing'||!state.paired)return;const actor=el.dataset.breathActor,action=el.dataset.breathAction;if(!M.USERS.includes(actor))return;const b=pair.breath;if(action==='open'){if(b?.status!=='waiting'||b.from===actor||b.id!==el.dataset.breathId)return;breathInviteOpened=b.id;if(actor===other())breathPeerDetail=true;const notice=pair.notices.find(n=>n.to===actor&&n.target===b.id&&n.kind==='breath');if(notice)pair=M.reduce(pair,actor,{type:'read',id:notice.id});render();return}if(!['invite','join','cancel'].includes(action))return;if(action==='join'&&breathInviteOpened!==b?.id)return;const consent=document.querySelector(`[data-breath-consent="${actor}"]`)?.checked===true;if(['invite','join'].includes(action)&&!consent){document.querySelector(`[data-breath-error="${actor}"]`).textContent='함께 기록할 내용을 확인하고 동의해 주세요.';return}pair=M.reduce(pair,actor,{type:'breath-'+action,consent});if(action==='invite')breathPeerDetail=actor===other();if(action==='cancel'){breathPeerDetail=false;breathPeerView='today'}render();});
let datePrivate=null,dateHeartShares=[],dateInviteOpened='',dateManual=false,dateNearby=false;
function dateAutoSync(){if(!state.paired||dateManual)return;if(dateNearby&&(!pair.dateSession||pair.dateSession.status==='cancelled')){pair=M.reduce(pair,who,{type:'date-auto-start'});if(pair.dateSession?.status==='active')datePrivateStart()}else if(!dateNearby&&pair.dateSession?.status==='active'){pair=M.reduce(pair,who,{type:'date-end'});for(const actor of M.USERS)if(datePrivate)SAIDateHeart.stop(datePrivate.people[actor]);}}

const dateDailyHigh={sumin:138,jiwoo:126};
function datePrivateStart(){datePrivate={id:pair.dateSession.id,tick:0,people:Object.fromEntries(M.USERS.map(id=>[id,window.SAIDateHeart.create(dateDailyHigh[id])]))};}
function dateLive(actor){const h=datePrivate?.people[actor];if(!h)return '';return `<div class="date-heart-value"><small>지금 내 심박</small><strong>${h.current??'—'} <small>bpm</small></strong></div><div class="stats-row"><span>나의 오늘 최고 심박</span><b>${h.baseline} bpm</b></div><div class="info" role="status">${h.window?'최고치를 넘어선 순간부터 관찰 중 · '+Math.max(0,20-Math.floor((Date.now()-h.window.start)/1000))+'초 남음':'오늘 최고치를 넘으면 20초 동안 관찰해요.'}</div>`}
function dateMomentCards(actor){const h=datePrivate?.people[actor];return (h?.moments||[]).slice().reverse().map(m=>`<article class="share-card" data-date-moment="${m.id}">${pair.dateSession?.status==='done'?`<label class="check-row"><input type="checkbox" data-date-select="${m.id}" data-date-owner="${actor}" ${m.selected?'checked':''}><span>이 순간을 공유 캘린더에 남기기</span></label>`:''}<small>${m.note?'나만의 기록':m.dismissed?'나중에 남길 순간':'새로운 최고 심박 · 나에게만 온 알림'}</small><h3>20초 동안 최고 ${m.peak} bpm</h3><p>그때 어떤 순간이었나요?</p>${m.note?`<p class="shared-note">${esc(m.note)}</p>`:`<label class="tiny" for="date-note-${actor}-${m.id}">그 순간의 메모</label><textarea id="date-note-${actor}-${m.id}" data-date-note="${m.id}" data-date-owner="${actor}" maxlength="300" placeholder="함께 웃었거나, 계단을 올랐을 수도 있어요.">${esc(m.draft)}</textarea><button class="primary" data-date-action="note" data-date-actor="${actor}" data-date-id="${m.id}">나만의 메모 저장</button>${!m.dismissed?`<button class="text-btn" data-date-action="later" data-date-actor="${actor}" data-date-id="${m.id}">나중에 적기</button>`:''}`}</article>`).join('')}
function dateScreen(actor){const d=pair.dateSession,own=actor===who;const button=(label,action,cls='primary')=>`<button class="${cls}" data-date-action="${action}" data-date-actor="${actor}">${label}</button>`;const agree=`<label class="check-row"><input type="checkbox" data-date-consent="${actor}"><span>내 심박을 확인하고, 최고치를 넘은 순간을 나만의 기록으로 남길게요.</span></label>`;let body='';if(!state.paired)body=msg('파트너를 연결하면 함께 시작할 수 있어요.')+btn('파트너 연결하기','invite');else if(!d||['cancelled','done'].includes(d.status)){if(d?.status==='cancelled')body+=msg('데이트 기록을 취소했어요.');if(d?.status!=='done')body+=`<div class="stats-row"><span>나의 오늘 최고 심박</span><b>${dateDailyHigh[actor]} bpm</b></div>`+(dateManual?agree+button('데이트 시작 초대하기','invite'):msg('같은 공간에 있는 것이 감지되면 각자의 심박 기록이 자동으로 시작돼요.'));}else if(d.status==='waiting'){body=d.from===actor?msg('상대가 수락하면 각자의 심박 기록을 시작해요.')+button('초대 취소','cancel','text-btn'):dateInviteOpened===d.id?msg('함께 데이트를 시작하자는 초대가 왔어요.')+agree+button('수락하고 데이트 시작','join')+button('지금은 어려워요','cancel','text-btn'):msg('함께할 데이트를 기다리고 있어요. 초대가 오면 상단 알림에서 확인해 주세요.');}if(d&&['active','done'].includes(d.status)){body+=`<div class="center"><small>${status(d.status)}</small><div data-date-clock>${elapsed(d)}</div></div><p class="tiny">심박과 알림은 각자 확인해요. 데이트를 마친 뒤 원하는 순간만 골라 공유할 수 있어요.</p>${d.status==='active'?`<div data-date-live="${actor}">${dateLive(actor)}</div>`:msg('데이트를 마쳤어요. 관찰 중이던 구간은 알림 없이 종료했어요.')}<div data-date-moments="${actor}" aria-live="polite">${dateMomentCards(actor)}</div>`;body+=d.status==='active'?button('데이트 마치기','end')+button('기록 취소','cancel','text-btn'):`<p class="tiny">선택한 순간의 최고 심박·시각·저장한 메모가 상대와 함께 보는 캘린더에 남아요. 작성 중인 메모는 먼저 저장해 주세요.</p><button class="primary" data-date-action="share-selected" data-date-actor="${actor}">선택한 순간 캘린더에 반영하기</button><p role="status" data-date-share-status="${actor}">${datePrivate?.people[actor]?.shareMessage||'아직 선택하지 않은 순간은 나에게만 남아요.'}</p>`+btn('공유 캘린더 보기','calendar','secondary')+button('새 데이트 기록','new-session','text-btn');}return formPage(SAIWeek.header('OUR DATE','','',true,{backAttrs:'data-go="together"',backLabel:'우리로 돌아가기',trendSuffix:false})+`<h2>데이트 기록</h2><section class="date-record-settings"><label class="check-row"><span class="grow">수동 기록<small>${dateManual?'초대하고 수락하면 기록을 시작해요.':'같은 공간에 있으면 자동으로 기록해요.'}</small></span><input type="checkbox" role="switch" data-date-manual ${dateManual?'checked':''} ${d&&['active','waiting'].includes(d.status)?'disabled':''}></label><p class="tiny">${dateNearby?'같은 공간에 있어요':'함께 있는 순간을 기다리고 있어요'} · ${dateManual?'수동':'자동'} 기록</p>${own?`<details class="date-proximity-demo"><summary>근접 감지 상태 설정</summary><label class="check-row"><input type="checkbox" data-date-nearby ${dateNearby?'checked':''}><span>같은 공간에 있어요</span></label></details>`:''}</section>`+body+`<p class="error" role="alert" data-date-error="${actor}"></p>`)}
function dateNotice(actor){const device=actor===who?app.closest('.device'):document.getElementById('date-peer-device');if(!device)return;device.querySelector('.date-peak-notice')?.remove();const m=datePrivate?.people[actor]?.moments.findLast(m=>!m.note&&!m.dismissed);if(!m||pair.dateSession?.status!=='active')return;device.insertAdjacentHTML('beforeend',`<div class="ios-notification date-peak-notice"><button class="invite-notice" data-date-action="open-note" data-date-actor="${actor}" data-date-id="${m.id}"><small>나에게만 · 20초 관찰 완료</small><strong>그 순간, 최고 ${m.peak} bpm</strong><span>어떤 순간이었는지 남겨볼까요? →</span></button></div>`);}
function renderDatePeer(){document.querySelectorAll('.date-invite-notice').forEach(el=>el.remove());let peer=document.getElementById('date-peer-device');document.body.classList.toggle('date-dual',current==='date-session');if(current!=='date-session'){peer?.remove();document.querySelectorAll('.date-peak-notice').forEach(el=>el.remove());return}document.body.classList.add('dual-invite');if(!peer){peer=document.createElement('section');peer.id='date-peer-device';peer.className='device';peer.setAttribute('aria-label','데이트 상대 화면');app.closest('.device').after(peer)}peer.innerHTML=`<div class="status"><b>9:41</b><div>▮▮▮ &nbsp; ◒ &nbsp; ▰</div></div><div class="peer-app">${dateScreen(other())}</div><div class="home-line"></div>`;dateNotice(who);dateNotice(other());const d=pair.dateSession;if(d?.status==='waiting'&&dateInviteOpened!==d.id){const actor=M.other(d.from),device=actor===who?app.closest('.device'):peer;const notice=inviteNotice(esc(person(d.from))+'님이 데이트에 초대했어요','date-invite-open').replace('data-action="date-invite-open"',`data-date-action="open-invite" data-date-actor="${actor}" data-date-id="${d.id}"`);device.insertAdjacentHTML('beforeend',`<div class="ios-notification date-invite-notice">${notice}</div>`);}}
function dateRefresh(){const pages=[app.querySelector('.page'),document.querySelector('#date-peer-device .page')],positions=pages.map(p=>p?.scrollTop||0);render();[app.querySelector('.page'),document.querySelector('#date-peer-device .page')].forEach((p,i)=>{if(p)p.scrollTop=positions[i]});}
document.addEventListener('change',e=>{if(e.target.matches('[data-date-manual]')){if(['active','waiting'].includes(pair.dateSession?.status))return;dateManual=e.target.checked;dateAutoSync();dateRefresh();return}if(e.target.matches('[data-date-nearby]')){dateNearby=e.target.checked;dateAutoSync();dateRefresh();return}});
document.addEventListener('change',e=>{const el=e.target.closest('[data-date-select]');if(!el||pair.dateSession?.status!=='done')return;const h=datePrivate?.people[el.dataset.dateOwner],m=h?.moments.find(m=>m.id===Number(el.dataset.dateSelect));if(m){m.selected=el.checked;h.shareMessage='선택이 바뀌었어요. 반영하기를 눌러 저장해 주세요.';document.querySelector(`[data-date-share-status="${el.dataset.dateOwner}"]`).textContent=h.shareMessage;}});
document.addEventListener('input',e=>{const el=e.target.closest('[data-date-note]');if(!el)return;const m=datePrivate?.people[el.dataset.dateOwner]?.moments.find(m=>m.id===Number(el.dataset.dateNote));if(m)m.draft=el.value;});
document.addEventListener('click',e=>{const b=e.target.closest('[data-date-action]');if(!b||current!=='date-session'||!state.paired)return;const actor=b.dataset.dateActor;if(!M.USERS.includes(actor))return;if(b.dataset.dateAction==='new-session'){if(pair.dateSession?.status!=='done')return;pair.dateSession=null;datePrivate=null;dateAutoSync();dateRefresh();return}if(b.dataset.dateAction==='open-invite'){const d=pair.dateSession;if(d?.status!=='waiting'||d.from===actor||d.id!==b.dataset.dateId)return;dateInviteOpened=d.id;pair=M.reduce(pair,actor,{type:'read',id:pair.notices.find(n=>n.to===actor&&n.target===d.id&&n.kind==='date')?.id});dateRefresh();return}if(b.dataset.dateAction==='open-note'){b.closest('.date-peak-notice')?.remove();document.querySelector(`[data-date-moments="${actor}"] [data-date-moment="${b.dataset.dateId}"]`)?.scrollIntoView({block:'center',behavior:'smooth'});return}const action=b.dataset.dateAction,consent=document.querySelector(`[data-date-consent="${actor}"]`)?.checked===true;if(action==='share-selected'){if(pair.dateSession?.status!=='done'||datePrivate?.id!==pair.dateSession.id)return;const h=datePrivate.people[actor],chosen=h.moments.filter(m=>m.selected);dateHeartShares=dateHeartShares.filter(r=>r.session!==datePrivate.id||r.from!==actor);dateHeartShares.push(...chosen.map(m=>({id:'date-heart-'+datePrivate.id+'-'+actor+'-'+m.id,session:datePrivate.id,from:actor,day:pair.dateSession.day,sharedAt:Date.now(),peak:m.peak,peakAt:m.peakAt,note:m.note})));h.shareMessage=chosen.length?chosen.length+'개의 순간을 공유 캘린더에 남겼어요.':'공유한 심박을 모두 해제했어요. 개인 기록은 그대로 남아요.';dateRefresh();return}if(['note','later'].includes(action)){const m=datePrivate?.people[actor]?.moments.find(m=>m.id===Number(b.dataset.dateId));if(!m)return;if(action==='note'){if(!m.draft.trim()){document.querySelector(`[data-date-error="${actor}"]`).textContent='그 순간의 이야기를 적어주세요.';return}m.note=m.draft.trim()}else m.dismissed=true;dateRefresh();return}if(action==='join'&&dateInviteOpened!==pair.dateSession?.id)return;if(['invite','join'].includes(action)&&!consent){document.querySelector(`[data-date-error="${actor}"]`).textContent='기록할 내용을 확인하고 동의해 주세요.';return}pair=M.reduce(pair,actor,{type:'date-'+action,consent});if(action==='join'&&pair.dateSession.status==='active')datePrivateStart();if(['end','cancel'].includes(action)&&datePrivate){for(const id of M.USERS)window.SAIDateHeart.stop(datePrivate.people[id]);if(action==='cancel')datePrivate=null;}dateRefresh();});
setInterval(()=>{if(pair.dateSession?.status!=='active'||datePrivate?.id!==pair.dateSession.id)return;datePrivate.tick++;for(const [i,actor] of M.USERS.entries()){const h=datePrivate.people[actor],t=datePrivate.tick;const wave=[-8,-4,1,4,2,7,5,9,3,6,2,0,-3,-6,-9,-5,-4,-6,-8,-10,-8,-6,-4,-2,-5,-7,-8,-6,-5,-4];const bpm=(actor==='sumin'?138:126)+wave[(t+(i?20:0))%wave.length]+Math.floor(t/60)*3;const before=h.moments.length;window.SAIDateHeart.sample(h,bpm,Date.now());dateDailyHigh[actor]=h.baseline;const live=document.querySelector(`[data-date-live="${actor}"]`);if(live)live.innerHTML=dateLive(actor);if(h.moments.length>before){const box=document.querySelector(`[data-date-moments="${actor}"]`);if(box)box.insertAdjacentHTML('afterbegin',dateMomentCards(actor).split('</article>')[0]+'</article>');dateNotice(actor);}}},1000);
let morningPeerView='today';
function morningPeerHome(){if(morningPeerView==='today')return receiverToday('data-morning-peer-go');const saved=state.peerView;state.peerView=morningPeerView;try{return (formPage(peerPage())+peerNav()).replaceAll('data-peer-go=','data-morning-peer-go=')}finally{state.peerView=saved}}
function renderMorningPeer(){let peer=document.getElementById('morning-peer-device');if(current!=='morning'){peer?.remove();morningPeerView='today';return}document.body.classList.add('dual-invite');if(!peer){peer=document.createElement('section');peer.id='morning-peer-device';peer.className='device';peer.setAttribute('aria-label','아침 기록 받는 사람 화면');app.closest('.device').after(peer)}const m=pair.mornings?.[who];const opened=m&&morningOpened.has(m.id);peer.innerHTML=`<div class="status"><b>9:41</b><div>▮▮▮ &nbsp; ◒ &nbsp; ▰</div></div><div class="peer-app">${opened?formPage(SAIWeek.header('YOUR MORNING','','',true,{backAttrs:'data-morning-home',backLabel:'오늘로 돌아가기',trendSuffix:false})+`<h2>${esc(person(who))}님의 아침</h2><p class="sub">나에게 전해준 ${m.day.split('-').map((v,i)=>Number(v)+['년','월','일'][i]).join(' ')}의 기록이에요.</p>`+summary(m.values)+morningExtras(m)+msg('확인했어요. 상대에게도 확인 상태가 표시돼요.')):morningPeerHome()}</div><div class="home-line"></div>${m&&!m.seen&&!opened?`<div class="ios-notification" role="status" aria-live="polite"><button class="invite-notice" data-x="morning-open" data-id="${m.id}" data-to="${other()}"><small>SAI · 지금</small><strong>${esc(person(who))}님이 아침 기록을 보냈어요</strong><span>보기 →</span></button></div>`:''}`}
document.addEventListener('click',e=>{const link=e.target.closest('[data-morning-peer-go]');if(link){morningPeerView=['sleep','activity','heart','calendar','settings'].includes(link.dataset.morningPeerGo)?link.dataset.morningPeerGo:'today';renderMorningPeer()}if(e.target.closest('[data-morning-home]')){const m=pair.mornings?.[who];if(m)morningOpened.delete(m.id);morningPeerView='today';renderMorningPeer()}});

function receivedNotes(){return state.records.filter(r=>r.shared&&r.from!==who).map(r=>`<div class="share-card"><span class="eyebrow">상대가 전한 ${r.type==='sleep'?'아침':'순간'}</span><h3>${esc(r.title)}</h3><p>${esc(r.note)}</p><p>${r.type==='sleep'?'수면 7시간 24분':'심박 '+(r.peakBpm??68)+' bpm'}</p>${r.seen?'<small>확인한 기록이에요.</small>':X('마음, 잘 받았어','record-seen',{id:r.id},'primary')}</div>`).join('')}
const careNeeds={quiet:'조용히 함께 쉬고 싶어',food:'식사를 챙겨주면 좋겠어',call:'잠깐 통화하고 싶어',space:'혼자 쉬는 시간이 필요해',walk:'가볍게 같이 걷고 싶어',date:'함께 즐거운 시간을 보내고 싶어'};
const careName=k=>k==='data'?'내 생체 기록을 보냈어요':careNeeds[k]||'배려를 전해요';
const careStatus=k=>({requested:'답장을 기다려요',accepted:'내가 챙길게',done:'배려를 전했어요',cancelled:'요청을 취소했어요'}[k]);
function careFacts(){const d=M.data(who),health=window.SAIHealthCards.values(M.TODAY),past=Array.from({length:7},(_,i)=>{const dt=new Date(M.TODAY+'T12:00:00Z');dt.setUTCDate(dt.getUTCDate()-i-1);return M.data(who,dt.toISOString().slice(0,10)).sleep}),avg=Math.round(past.reduce((a,b)=>a+b,0)/7),diff=d.sleep-avg;return [{key:'sleep',label:'지난밤 수면',value:value(d.sleep,'sleep'),detail:'이전 7일 평균 '+value(avg,'sleep')+' · '+(diff===0?'평균과 같아요':Math.abs(diff)+'분 '+(diff>0?'길어요':'짧아요'))},{key:'steps',label:'오늘의 걸음',value:(window.SAIActivity?.daily(M.TODAY).steps??d.steps).toLocaleString()+' 걸음',detail:'오늘 누적 · 하루가 끝나기 전의 기록이에요'},{key:'bpm',label:'안정 심박',value:d.bpm+' bpm',detail:'활동 중 심박과 구분한 요약 수치예요'},{key:'energy',label:'에너지 점수',value:health.energy+'점',detail:'기록을 가져온 시점의 에너지 점수'},{key:'stress',label:'스트레스',value:health.stress+'점',detail:'기록을 가져온 시점의 스트레스 점수'}]}
let careDataDraft=null,careDemoReply='',careOpened='',carePeerView='today';const careViewed=new Set();
function careBoard(){const panel=(id,label,html)=>`<section class="care-board-panel" data-care-panel="${id}"><div class="care-board-phone"><div class="status"><b>9:41</b><div>▮▮▮ &nbsp; ◒ &nbsp; ▰</div></div><div class="care-panel-content">${html.replaceAll('id="x-error"',`id="${id}-error"`)}</div><div class="home-line"></div></div></section>`;return `<div class="care-board"><section class="care-board-row"><div class="care-board-pair">${panel('care-send','보내는 화면',careDataPage())}${panel('care-receive','받는 화면',careReceivePage())}</div></section></div>`}
function renderCareBoard(){const positions=[...app.querySelectorAll('[data-care-panel]')].map(p=>[p.dataset.carePanel,p.querySelector('.page')?.scrollTop||0]);const x=window.scrollX,y=window.scrollY;render();for(const [id,top] of positions){const page=app.querySelector(`[data-care-panel="${id}"] .page`);if(page)page.scrollTop=top}window.scrollTo(x,y)}

function captureCareData(){const facts=careFacts(),getDay=day=>({...M.data(who,day),...window.SAIHealthCards.values(day)}),health=getDay(M.TODAY),samples=window.SAIHealthCards.series(health,'stress').map((v,i)=>({time:String(i).padStart(2,'0')+':00',value:v}));return {day:M.TODAY,capturedAt:Date.now(),context:facts.map(f=>({...f})),note:'',comparison:SAICareComparison.build(M.TODAY,getDay,samples)}}
function careDataCard(d){return `<article class="share-card"><small>가져온 기록 · ${esc(d.day)}</small>${d.context.map(f=>`<div class="stats-row"><span>${esc(f.label)}</span><b>${esc(f.value)}</b></div>`).join('')}${d.note?`<p class="shared-note">${esc(d.note)}</p>`:''}</article>`+SAICareComparison.render(d.comparison)}
function careDataPage(){const sent=pair.cares.find(c=>c.from===who&&c.need==='data'&&c.day===M.TODAY&&!['done','cancelled'].includes(c.status));if(sent)return page('care-data','내 기록을 전했어요','상대에게 수치와 비교 기록을 보냈어요.',careDataCard(sent)+X('공유 요청 취소','care-cancel',{id:sent.id},'secondary')+btn('공유 캘린더 보기','calendar','text-btn'));return page('care-data','말로 다 설명하기<br>어려운 날에는.','현재 수치와 최근 7일의 변화를 함께 전해요.',(careDataDraft?`<div class="section-label"><span>보내기 전 확인</span></div><p class="tiny">아래 수면·걸음·안정 심박·에너지 점수·스트레스와 최근 7일 비교와 기준별 표시가 함께 전달돼요. 아직 공유되지 않았어요.</p>${careDataCard(careDataDraft)}<label class="care-message" for="care-data-note">덧붙이고 싶은 말 <small>선택</small></label><textarea id="care-data-note" maxlength="300" placeholder="느낌을 고르지 않아도 괜찮아요.">${esc(careDataDraft.note)}</textarea><p class="tiny">기록을 보낸다고 앞으로의 데이터가 자동 공유되지는 않아요.</p><button class="primary" data-care-data-send>생체 기록 보내기</button><button class="text-btn" data-care-data-clear>가져온 기록 지우기</button>`:`<article class="care-reading"><small>내가 시작하는 공유</small><h3>내가 가져오고,<br>확인한 뒤 보내요.</h3><p>수면·걸음·안정 심박·에너지 점수·스트레스를 한 장으로 준비해요. 상대에게 보일 수치와 최근 7일 비교를 먼저 확인할 수 있어요.</p><p class="tiny">이 화면을 열기만 해서는 기록을 가져오거나 보내지 않아요.</p></article><button class="primary" data-care-data-load>내 생체 기록 가져오기</button>`))}
function latestCare(){return state.paired?pair.cares.find(c=>c.from===who&&c.to===other()&&c.need==='data'&&c.status!=='cancelled'):null}
function careNotification(){const d=latestCare();return d&&!careViewed.has(d.id)?`<div class="ios-notification" role="status" aria-live="polite"><button class="invite-notice" data-care-open="${esc(d.id)}"><small>SAI · 지금</small><strong>${esc(person(d.from))}님이 생체 기록을 보냈어요</strong><span>보기 →</span></button></div>`:''}
function careReceivePage(){const d=latestCare();if(!d||careOpened!==d.id){if(carePeerView==='today')return receiverToday('data-care-peer-go');const saved=state.peerView;state.peerView=carePeerView;try{return (formPage(peerPage())+peerNav()).replaceAll('data-peer-go=','data-care-peer-go=')}finally{state.peerView=saved}}return page('care-data-receive','기록 너머의 하루를,<br>조금 더 이해해요.','상대가 직접 보내준 기록을 바탕으로 해요.',careDataCard(d)+(window.SAIComments?.render(d.id,other())||'')).replace('data-go="together" aria-label="우리로 돌아가기"','data-care-home aria-label="오늘로 돌아가기"')}
document.addEventListener('click',e=>{const open=e.target.closest('[data-care-open]');if(open){const d=latestCare();if(!d||d.id!==open.dataset.careOpen)return;careOpened=d.id;careViewed.add(d.id);pair.notices.filter(n=>n.to===d.to&&n.target===d.id).forEach(n=>n.read=true);renderCareBoard();app.querySelector('[data-care-panel="care-receive"] .page').scrollTop=0;return}if(e.target.closest('[data-care-home]')){careOpened='';carePeerView='today';renderCareBoard();app.querySelector('[data-care-panel="care-receive"] .page').scrollTop=0;return}const link=e.target.closest('[data-care-peer-go]');if(link){carePeerView=['sleep','activity','heart','calendar','settings'].includes(link.dataset.carePeerGo)?link.dataset.carePeerGo:'today';renderCareBoard()}});
document.addEventListener('input',e=>{if(e.target.id==='care-data-note'&&careDataDraft)careDataDraft.note=e.target.value});
document.addEventListener('click',e=>{if(e.target.closest('[data-care-data-load]')){careDataDraft=captureCareData();renderCareBoard()}if(e.target.closest('[data-care-data-clear]')){careDataDraft=null;renderCareBoard()}if(e.target.closest('[data-care-data-send]')&&careDataDraft&&state.paired){const sent=pair.cares.find(c=>c.from===who&&c.need==='data'&&c.day===M.TODAY&&!['done','cancelled'].includes(c.status));if(sent){document.getElementById('care-send-error').textContent='이미 보낸 생체 기록이 있어요. 배려 화면에서 기존 요청을 취소한 뒤 다시 보낼 수 있어요.';return}pair=M.reduce(pair,who,{type:'care',need:'data',...careDataDraft,consent:true});careDataDraft=null;renderCareBoard()}});


const modeName=k=>({rest:'편안하게 쉬기',light:'가볍게 산책하기',active:'활기차게 나들이'}[k]||'아직 선택 전');
const markName=k=>({hand:'손잡은 순간',laugh:'함께 웃은 순간',view:'같은 풍경'}[k]);
const elapsed=d=>{const sec=d.status==='done'?(pair.memories.find(m=>m.id===d.id)?.seconds||0):Math.max(0,Math.floor((Date.now()-d.started)/1000));return String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0')};
const noticeReads=new Set();let openNotice='';
function allNotices(){
 const records=(window.SAIShared?.library()||[]).filter(r=>r.from!==who&&r.kind!=='summary');
 const native=pair.notices.filter(n=>n.to===who&&n.kind!=='message').map(n=>({...n,record:(n.kind==='comment'?(window.SAIShared?.library()||[]):records).find(r=>r.id===(n.target||n.id)),title:n.title||noticeName(n.kind),stamp:n.at||0}));
 const represented=new Set(native.filter(n=>!/-seen$|accepted|done|cancelled/.test(n.kind)).map(n=>n.target||n.id));
 const extra=records.filter(r=>!represented.has(r.id)).map(r=>({id:'shared-'+r.id,kind:r.kind,day:r.day,stamp:r.sharedAt||0,title:r.from==='both'?'함께 남긴 기록이 있어요':r.title+' 기록이 도착했어요',record:r}));
 return [...native,...extra].map(n=>({...n,read:n.read||noticeReads.has(n.id)})).sort((a,b)=>b.stamp-a.stamp||b.day.localeCompare(a.day));
}
function noticesPage(){const rows=allNotices(),unread=rows.filter(n=>!n.read).length;return formPage(SAIWeek.header('NOTIFICATIONS','','',true,{backAttrs:'data-go="together"',backLabel:'우리로 돌아가기',trendSuffix:false})+`<div class="notice-toolbar"><div class="notice-counts" aria-live="polite"><span>전체 <b>${rows.length}</b></span><span class="notice-unread-count ${unread?'has-unread':''}">안 읽음 <b>${unread}</b></span></div><button class="notice-read-all" data-notice-all ${unread?'':'disabled'}>모두 읽음</button></div>`+(!state.paired?msg('파트너를 연결하면 받은 알림이 여기에 쌓여요.')+btn('파트너 연결하기','invite'):rows.length?rows.map(n=>{const r=n.record,route=({breath:'breathing',walk:'walk',date:'date-session',care:'care',garden:'garden',partner:'together',morning:'morning',pulse:'received',mode:'planning',slots:'availability',slot:'availability'}[n.kind.split('-')[0]]);return `<article class="notice-item ${n.read?'':'unread'}" data-notice-kind="${esc(n.kind)}"><button class="row" data-notice-open="${esc(n.id)}" aria-expanded="${openNotice===n.id}"><span class="grow"><strong>${esc(n.title)}</strong><small>${esc(n.day)} · ${n.read?'읽음':'새 알림'}</small></span><span>${openNotice===n.id?'−':'＋'}</span></button>${openNotice===n.id?`<div class="notice-body">${r?`<h3>${esc(r.title)}</h3>${r.heartSamples?window.SAIMoment?.chart(r.heartSamples)||'':''}${(r.values||[]).map(([l,v])=>`<div class="stats-row"><span>${esc(l)}</span><b>${esc(v)}</b></div>`).join('')}${r.note?`<p>${esc(r.note)}</p>`:''}`:route?'<p class="tiny">해당 화면에서 초대와 응답 상태를 확인할 수 있어요.</p>':'<p class="tiny">알림을 확인했어요. 공유가 해제된 기록은 내용이 표시되지 않아요.</p>'}${route?btn('관련 화면 보기',route,'secondary'):''}${r?`<button class="secondary" data-notice-calendar="${esc(r.day)}">공유 캘린더에서 보기</button>`:''}</div>`:''}</article>`}).join(''):msg('아직 받은 알림이 없어요.')))}
document.addEventListener('click',e=>{const item=e.target.closest('[data-notice-open]');if(item){const id=item.dataset.noticeOpen;const targetNotice=allNotices().find(n=>n.id===id);if(!targetNotice)return;if(targetNotice.kind==='comment'&&targetNotice.record){window.SAIComments.open(targetNotice.record.id,id);return}noticeReads.add(id);const n=pair.notices.find(n=>n.id===id&&n.to===who);if(n)n.read=true;openNotice=openNotice===id?'':id;const y=app.querySelector('.page')?.scrollTop||0;render();app.querySelector('.page').scrollTop=y}if(e.target.closest('[data-notice-all]')){allNotices().forEach(n=>noticeReads.add(n.id));pair.notices.filter(n=>n.to===who).forEach(n=>n.read=true);render()}const calendar=e.target.closest('[data-notice-calendar]');if(calendar){window.SAIShared?.focusDay(calendar.dataset.noticeCalendar);go('calendar')}});
const noticeName=k=>({'breath-joined':'함께 호흡 초대를 수락했어요','breath-cancelled':'함께 호흡이 취소됐어요','walk-joined':'함께 걷기 초대를 수락했어요','walk-cancelled':'함께 걷기가 취소됐어요','date-joined':'데이트 기록 초대를 수락했어요','date-ended':'데이트 기록을 마쳤어요','date-cancelled':'데이트 초대가 취소됐어요','care-cancelled':'배려 요청이 취소됐어요',checkin:'오늘의 기분을 공유했어요',cycle:'생리 기록을 공유했어요',partner:'파트너와 연결됐어요','journal':'나에게 남긴 순간이 도착했어요','morning':'아침 기록이 도착했어요','morning-seen':'상대가 아침을 확인했어요',pulse:'심박이 도착했어요','pulse-seen':'네 리듬을 느꼈어',breath:'함께 호흡 초대',walk:'함께 걷기 초대',date:'데이트 기록 초대',garden:'정원에 함께하고 있어요',message:'새 메시지가 있어요',care:'필요한 배려를 전했어요','care-accepted':'내가 챙길게','care-done':'배려를 전했어요',mode:'데이트 선택이 바뀌었어요','mode-agreed':'데이트 약속이 정해졌어요',slots:'편한 시간이 바뀌었어요',slot:'통화 시간을 골랐어요'}[k]||'함께한 활동에 새 소식이 있어요');
function dispatch(a,actor=who){pair=M.reduce(pair,actor,{...a,consent:true});render()}
function needConsent(){if(!document.getElementById('x-consent')?.checked){extraError='공유할 내용과 참여 동의를 확인해 주세요.';document.getElementById('x-error').textContent=extraError;return false}return true}
function calendarPage(){const [y,m]=calendarMonth.split('-').map(Number),days=new Date(y,m,0).getDate(),offset=(new Date(y,m-1,1).getDay()+6)%7;state.day=Math.min(state.day,days);const date=calendarMonth+'-'+String(state.day).padStart(2,'0');return formPage(`<div class="top"><span class="logo">sai</span><small>우리의 순간</small></div>`+title('MOMENTS','작은 순간이 모이는 곳','나의 메모부터 함께한 활동까지.')+SAIWeek.render({id:'personal-week',label:'개인 기록',day:date,min:'2026-01-01',max:'2026-12-31',legend:'게이지: 기록 유무',getGauge:day=>{const has=visibleCycles().some(r=>day>=r.start&&day<=(r.end||r.start))||pair.events.some(e=>e.day===day)||state.records.some(r=>(r.day||M.TODAY)===day)||['2026-10-03','2026-10-10'].includes(day);return {values:[has?1:0],label:has?'기록 있음':'기록 없음'}},onSelect:day=>{calendarMonth=day.slice(0,7);state.day=Number(day.slice(8));render()}})+`<h3>${m}월 ${state.day}일</h3>${cycleCalendarCards(date)}${calendarMonth==='2026-10'?calendarItems():msg('선택한 날짜의 공동 활동을 아래에서 확인하세요.')}<div class="push">${action('새로운 순간 남기기','share-heart','secondary')}</div>`)+nav()}
function decorate(id){document.body.classList.toggle('care-board-mode',['care','care-data','care-receive','care-data-receive'].includes(id));renderMorningPeer();renderDatePeer();renderBreathPeer();const carePhone=app.querySelector('[data-care-panel="care-receive"] .care-board-phone');if(carePhone)carePhone.insertAdjacentHTML('beforeend',careNotification());const p=app.querySelector('.page');if(!p)return;if(id==='together'){const morning=pair.mornings?.[who],link=p.querySelector('[data-go="morning"]');if(link&&morning?.day===M.TODAY){const badge=link.querySelector('.arrow');badge.className='morning-shared-badge';badge.textContent='공유 완료 ✓';link.querySelector('.grow small').textContent='오늘의 아침을 전했어요';link.setAttribute('aria-label','나의 아침 나누기, 오늘 공유 완료. 공유한 기록 보기');}}if(id==='calendar'){const date=calendarMonth+'-'+String(state.day).padStart(2,'0');const events=pair.events.filter(e=>e.day===date);const box=document.createElement('div');box.className='restored-events';box.innerHTML='<h3>함께한 활동</h3>'+events.map(e=>{let title=({breath:'24초 함께 호흡',walk:'각자의 걸음 목표 달성',garden:'우리의 꽃이 피었어요',call:e.hour+':00 통화 약속',mode:modeName(e.mode),care:careName(e.need),memory:'함께한 데이트'}[e.type]||'함께한 기록');const memory=pair.memories.find(m=>m.id===e.key);return `<div class="moment"><small>공동 기록 · ${e.day}</small><h3>${esc(title)}</h3>${memory?`<p>${memory.seconds}초 · 나 ${memory.bpm?.sumin??'비공개'} / 상대 ${memory.bpm?.jiwoo??'비공개'} bpm</p>${memory.marks.map(m=>`<p>${esc(person(m.by))} · ${markName(m.mark)}</p>`).join('')}`:''}</div>`}).join('');if(events.length)p.insertBefore(box,p.querySelector('.push'));}}
document.addEventListener('click',e=>{if(current!=='sharing')return;if(e.target.closest('[data-sharing-stop]')&&state.paired){for(const key of ['mood','sleep','heart','cycle'])pair=M.reduce(pair,who,{type:'share',key,value:false});render()}if(e.target.closest('[data-sharing-records]')&&state.paired){window.SAIShared.openSent();go('calendar')}});
window.SAIExtras={setSummarySharing(values){for(const key of ['mood','sleep','heart','cycle'])pair=M.reduce(pair,'sumin',{type:'share',key,value:values[key]===true})},nightData,nightGraph,breathChart,diaryShared(r){pair.notices.unshift({id:'notice-'+r.id+'-'+Date.now(),to:'jiwoo',kind:'diary',target:r.id,day:r.day,at:Date.now(),read:false,title:person('sumin')+'님이 일기를 공유했어요'})},diaryRead(id){pair.notices.filter(n=>n.kind==='diary'&&n.target===id).forEach(n=>n.read=true)},commentAdded(c,r){pair.notices.unshift({id:c.id,to:c.to,kind:'comment',target:r.id,day:r.day,at:c.at,read:false,title:person(c.from)+'님이 공유 기록에 댓글을 남겼어요'})},readCommentNotice(id){const n=pair.notices.find(n=>n.id===id&&n.kind==='comment');if(n)n.read=true},momentReceived(id){pair.notices.filter(n=>n.id===id&&n.to==='jiwoo').forEach(n=>n.read=true)},partnerConnected(){for(const to of M.USERS)pair.notices.unshift({id:'partner-connected-'+to+'-'+Date.now(),to,kind:'partner',day:M.TODAY,read:false});},content:featureContent,decorate,currentMonth(){calendarMonth='2026-10'},disconnect(){noticeReads.clear();openNotice='';breathInviteOpened='';breathPeerDetail=false;breathPeerView='today';dateInviteOpened='';dateManual=false;dateNearby=false;datePrivate=null;dateHeartShares=[];dateDailyHigh.sumin=138;dateDailyHigh.jiwoo=126;careDataDraft=null;careDemoReply='';careOpened='';carePeerView='today';careViewed.clear();cycleShares=[];pair=M.initial();who='sumin';morningOpened.clear();morningOptions.sumin={};morningOptions.jiwoo={}},recordSent(r){r.from='sumin';r.day=M.TODAY;r.sharedAt=Date.now();r.id='note-'+Date.now();r.seen=false;if(r.shared)pair.notices.unshift({id:r.id,to:'jiwoo',kind:'journal',day:M.TODAY,read:false});},moodUpdated(mood,note){pair=M.reduce(pair,'sumin',{type:'checkin',mood:({'편안해요':'calm','설레요':'excited','기분 좋아요':'happy','조금 흐려요':'cloudy','쉬고 싶어요':'tired'}[mood]||'calm'),note:note||''});},snapshot:()=>JSON.parse(JSON.stringify({...pair,cycleShares,dateHeartShares}))};
document.addEventListener('click',e=>{const b=e.target.closest('[data-x]');if(!b)return;extraError='';const a=b.dataset.x;if(a.startsWith('cycle')&&!canUseCycle())return;if(a==='health-card'){window.SAIHealthDetails.open(b.dataset.metric,selectedDay);return}if(a==='health-metric-row'){metric=b.dataset.metric;render();return}if(a==='health-view'){healthView=b.dataset.view;render();return}if(a==='health-day'){selectedDay=b.dataset.date;healthView='day';render();return}if(a==='month'){const [y,m]=calendarMonth.split('-').map(Number);const d=new Date(y,m-1+Number(b.dataset.delta),1);calendarMonth=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');render();return}if(a==='role'){who=b.dataset.who;render();return}if(a==='metric'){metric=b.dataset.metric;render();return}if(a==='period'){period=Number(b.dataset.period);render();return}if(a==='cycle-month'){const [y,m]=cycleMonth.split('-').map(Number);const d=new Date(Date.UTC(y,m-1+Number(b.dataset.delta),1));cycleMonth=d.toISOString().slice(0,7);render();return}if(a==='cycle-actual'){cycleDraft={start:M.TODAY,prediction:cyclePrediction()};go('cycle-log');return}if(a==='cycle-prediction-month'){cycleMonth=cyclePrediction().start.slice(0,7);render();return}if(a==='cycle-new'){cycleDraft={};go('cycle-log');return}if(a==='cycle-day'||a==='cycle-edit'){cycleDraft={...(cycleRecords.find(r=>b.dataset.date>=r.start&&b.dataset.date<=(r.end||r.start))||{start:b.dataset.date})};go('cycle-log');return}if(a==='cycle-demo'||a==='cycle-demo-off'){cycleDemo=a==='cycle-demo';render();return}if(a==='cycle-metric'){cycleMetric=b.dataset.metric;render();return}if(a==='cycle-share-open'){cycleShareStart=b.dataset.date;go('cycle-share');return}if(a==='cycle-unshare'){if(who!=='sumin')return;revokeCycle(b.dataset.date);render();return}if(a==='sleep-tab'){sleepTab=b.dataset.tab;render();return}if(a==='sleep-trend-metric'){sleepTrendMetric=b.dataset.metric;render();return}if(a==='sleep-trend-day'){sleepDay=b.dataset.date;sleepMonth=sleepDay.slice(0,7);sleepCalendarOpen=false;sleepTab='day';render();return}if(a==='sleep-day'){if(b.dataset.date>M.TODAY)return;sleepDay=b.dataset.date;sleepMonth=sleepDay.slice(0,7);sleepCalendarOpen=false;render();return}if(a==='sleep-calendar'){sleepCalendarOpen=!sleepCalendarOpen;render();return}if(a==='sleep-month'){const [y,m]=sleepMonth.split('-').map(Number),d=new Date(Date.UTC(y,m-1+Number(b.dataset.delta),1)),next=d.toISOString().slice(0,7);if(next>M.TODAY.slice(0,7))return;sleepMonth=next;render();return}if(a==='sleep-period'){sleepPeriod=Number(b.dataset.period);render();return}if(!state.paired&&!['cycle-save'].includes(a))return;
switch(a){case 'record-seen':{const r=state.records.find(r=>r.id===b.dataset.id&&r.from!==who&&r.shared);if(r){r.seen=true;pair.notices.forEach(n=>{if(n.id===r.id)n.read=true});render()}break}case 'morning-send':if(needConsent())dispatch({type:'morning-share',includeMood:document.querySelector('[data-morning-option="mood"]')?.checked===true,includeNote:document.querySelector('[data-morning-option="note"]')?.checked===true});break;case 'morning-open':{const m=pair.mornings?.[who];if(!m||m.id!==b.dataset.id||m.to!==b.dataset.to)return;morningOpened.add(m.id);dispatch({type:'morning-seen',id:m.id},m.to);break;}case 'morning-seen':case 'pulse-seen':case 'care-accept':case 'care-done':case 'care-cancel':dispatch({type:a,id:b.dataset.id});break;case 'pulse-value':pulseValue=Number(b.dataset.value);document.querySelectorAll('[data-x="pulse-value"]').forEach(btn=>btn.classList.toggle('on',Number(btn.dataset.value)===pulseValue));break;case 'pulse-send':if(needConsent())dispatch({type:'pulse',bpm:pulseValue});break;case 'invite':if(needConsent())dispatch({type:b.dataset.kind+'-invite'});break;case 'join':if(needConsent())dispatch({type:b.dataset.kind+'-join'});break;case 'cancel':dispatch({type:b.dataset.kind+'-cancel'});break;case 'walk-step':dispatch({type:'walk-step'});break;case 'garden-join':if(needConsent())dispatch({type:'garden-join'});break;case 'garden-sleep':dispatch({type:'garden-sleep'});break;case 'mode':dispatch({type:'mode',day:planDay,mode:b.dataset.mode});break;case 'slot':{const h=Number(b.dataset.hour),old=pair.slots[who];dispatch({type:'slots',hours:old.includes(h)?old.filter(n=>n!==h):[...old,h]});break}case 'slot-pick':dispatch({type:'slot-pick',hour:Number(b.dataset.hour)});break;case 'date-mark':dispatch({type:'date-mark',mark:b.dataset.mark});break;case 'date-end':dispatch({type:'date-end'});break;case 'sharing':if(!state.paired)return;dispatch({type:'share',key:b.dataset.key,value:!pair.people[who].sharing[b.dataset.key]});break;case 'cycle-share-send':{const r=cycleRecords.find(r=>r.start===cycleShareStart);if(!r||!needConsent())return;revokeCycle(r.start);const shared={id:'cycle-'+Date.now(),start:r.start,end:r.end,sharedAt:Date.now()};for(const key of ['symptom','flow','note'])if(document.querySelector('[data-cycle-field="'+key+'"]')?.checked)shared[key]=r[key];cycleShares.push(shared);pair.notices.unshift({id:shared.id,to:'jiwoo',kind:'cycle',day:r.start,target:shared.id,read:false});calendarMonth=r.start.slice(0,7);state.day=Number(r.start.slice(-2));who='sumin';window.SAIShared?.focusDay(r.start);go('calendar');break}case 'cycle-save':{const start=document.getElementById('cycle-start'),end=document.getElementById('cycle-end');if(!start.value||!start.reportValidity()||!end.reportValidity()||(end.value&&end.value<start.value)){document.getElementById('x-error').textContent='시작일과 종료일을 확인해 주세요.';return}const record={...(cycleDraft.prediction?{prediction:{...cycleDraft.prediction}}:{}),start:start.value,end:end.value,symptom:document.getElementById('cycle-symptom').value,flow:document.getElementById('cycle-flow').value,note:document.getElementById('cycle-note').value.trim()};if(cycleRecords.some(r=>r.start!==cycleDraft.start&&r.start!==record.start&&record.start<=(r.end||r.start)&&(record.end||record.start)>=r.start)){document.getElementById('x-error').textContent='기존 기록과 날짜가 겹쳐요. 기존 기록을 수정해 주세요.';return}revokeCycle(cycleDraft.start);revokeCycle(record.start);cycleRecords=cycleRecords.filter(r=>r.start!==record.start&&r.start!==cycleDraft.start);cycleRecords.push(record);cycleRecords.sort((a,b)=>a.start.localeCompare(b.start));cycleDraft={...record};cycleMonth=record.start.slice(0,7);pair=M.reduce(pair,'sumin',{type:'cycle',start:cycleRecords.at(-1).start,symptom:cycleRecords.at(-1).symptom});go('cycle');break} case 'notice':{const n=pair.notices.find(n=>n.id===b.dataset.id);dispatch({type:'read',id:n.id});if(n.kind==='cycle'){calendarMonth=n.day.slice(0,7);state.day=Number(n.day.slice(-2));window.SAIShared?.focusDay(n.day)}const routes={cycle:'calendar',partner:'together',journal:'received',morning:'received',pulse:'received',message:'notices',breath:'breathing',walk:'walk',date:'date-session',garden:'garden',care:'care',mode:'planning',slots:'availability',slot:'availability'};go(routes[n.kind.split('-')[0]]||'features');break}}});
document.addEventListener('change',e=>{if(e.target.id==='cycle-start'&&e.target.value&&e.target.reportValidity()){document.getElementById('cycle-end').min=e.target.value;}if(e.target.dataset.morningOption)morningOptions[who][e.target.dataset.morningOption]=e.target.checked;if(e.target.id==='trend-metric'){metric=e.target.value;render()}if(e.target.id==='history-day'){selectedDay=e.target.value;render()}if(e.target.id==='plan-day'){if(e.target.reportValidity()){planDay=e.target.value;render()}}if(e.target.id==='walk-goal')dispatch({type:'walk-goal',goal:Number(e.target.value)})});
setInterval(()=>{const b=pair.breath;if(b?.status==='running'){const seconds=Math.min(24,Math.floor((Date.now()-b.started)/1000));if(seconds>=24){dispatch({type:'breath-finish'});return}const previous=pair;pair=M.reduce(pair,who,{type:'breath-sample'});if(pair!==previous)document.querySelectorAll('[data-breath-hearts]').forEach(el=>el.innerHTML=breathChart(pair.breath.hearts));document.querySelectorAll('[data-breath-left]').forEach(el=>el.textContent=24-seconds);document.querySelectorAll('[data-breath-phase]').forEach(el=>el.textContent=Math.floor(seconds/4)%2?'천천히 내쉬어요':'천천히 들이쉬어요')}if(pair.dateSession?.status==='active'){document.querySelectorAll('[data-date-clock]').forEach(el=>el.textContent=elapsed(pair.dateSession))}},250);
rebuildIndex();render();
